begin;
create or replace function public.log_photo_meal(p_items jsonb,p_meal_type text,p_date date,p_time time)returns integer language plpgsql security definer set search_path='' as $$declare item jsonb;added integer:=0;food_id uuid;grams numeric;begin if auth.uid() is null then raise exception 'Authentication required';end if;if p_meal_type not in('breakfast','morning_snack','lunch','afternoon_snack','dinner','evening_snack')then raise exception 'Invalid meal type';end if;if jsonb_typeof(p_items)<>'array'or jsonb_array_length(p_items)<1 or jsonb_array_length(p_items)>20 then raise exception 'Photo meal must contain 1 to 20 foods';end if;for item in select value from jsonb_array_elements(p_items)loop food_id:=(item->>'food_id')::uuid;grams:=(item->>'grams')::numeric;if grams<=0 or grams>10000 then raise exception 'Invalid food amount';end if;perform public.log_food_entry_with_overrides(food_id,grams,p_meal_type,p_date,p_time,'Logged from reviewed meal photo','{}'::jsonb);added:=added+1;end loop;return added;end$$;
revoke all on function public.log_photo_meal(jsonb,text,date,time)from public,anon;
grant execute on function public.log_photo_meal(jsonb,text,date,time)to authenticated;
commit;
